 function validate(points){if(!Array.isArray(points)||points.length<2||points.length>21)throw Error('Use 2–21 waypoints');let previous=-1;for(const point of points){if(!point||!Number.isFinite(point.time)||point.time<0||point.time>60||point.time<=previous)throw Error('Waypoint times must increase from 0 to 60 seconds');previous=point.time;for(const axis of ['x','y','z'])if(!Number.isFinite(point[axis])||Math.abs(point[axis])>10000)throw Error('Waypoint positions must be between −10,000 and 10,000 cm');}if(points[0].time!==0)throw Error('The first waypoint starts at 0 seconds');}
