 function clear(effect){const points=read(effect);if(!points.length)return {...effect};const first=points[0];return {...effect,positionX:first.x,positionY:first.y,positionZ:first.z,animation:{...effect.animation,keys:effect.animation.keys.filter(key=>!isPosition(key))}};}
